'use strict';
const SeenTalk=(()=>{
 const dialog=document.createElement('dialog');dialog.id='npc-dialog';dialog.setAttribute('aria-describedby','npc-line');dialog.innerHTML='<button class="icon-close talk-close" type="button" aria-label="Close conversation">'+seenCloseIcon+'</button><p id="npc-line" class="talk-line" role="status"></p><div class="talk-options"></div>';document.body.append(dialog);let session=null,anchor=null,context=null,placementKey='',placementFrame=0;
 function requestPlacement(){placementKey='';if(!placementFrame)placementFrame=requestAnimationFrame(()=>{placementFrame=0;if(context&&dialog.open)nearby(context)})}
 const placementObserver=new ResizeObserver(requestPlacement);for(const element of [dialog,document.querySelector('.site-header'),document.querySelector('#scene-content')])placementObserver.observe(element);
 function finish(){const previous=session;if(!previous)return;session=null;anchor=null;previous.cancelDelay?.();SeenHub.releaseNpc(previous.person?.id);previous.onClose?.()}
 function begin(person){finish();session={person,revision:0};anchor=person;SeenHub.holdNpc(person);return session}
 function current(value){return session===value&&dialog.open}
 function close(){finish();if(dialog.open)dialog.close()}
 dialog.querySelector('.talk-close').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close()});dialog.addEventListener('close',()=>{if(dialog.open)return;finish();document.querySelector(document.body.dataset.scene==='screening'?'#room-world':document.body.dataset.scene==='arcade-room'?'#arcade-world':'#world').focus({preventScroll:true})});
 function show({name,role='CINEMA HOST',line,options=[],onClose}){const active=session;if(!active)return;const revision=++active.revision;if(onClose)active.onClose=onClose;placementKey='';dialog.setAttribute('aria-label',anchor?.name||name);dialog.querySelector('.talk-line').textContent=line;const actions=dialog.querySelector('.talk-options');actions.replaceChildren();for(const option of options){const button=document.createElement('button');button.type='button';button.textContent=option.label;button.onclick=()=>{if(current(active)&&active.revision===revision)return option.action()};actions.append(button)}actions.scrollTop=0;dialog.querySelector('.talk-line').scrollTop=0;if(!dialog.open){dialog.showModal();document.dispatchEvent(new Event('seen-conversation-open'))}seenSetStyle(dialog,'left',`${Math.max(10,(innerWidth-dialog.offsetWidth)/2)}px`);seenSetStyle(dialog,'top',`${Math.max(72,(innerHeight-dialog.offsetHeight)/2)}px`);dialog.querySelector('.talk-close').focus({preventScroll:true});actions.scrollTop=0;requestAnimationFrame(()=>{if(!current(active)||active.revision!==revision)return;if(context)nearby(context);actions.scrollTop=0;dialog.querySelector('.talk-line').scrollTop=0})}
 function canTalk(person){return !!context&&Math.hypot(person.x-context.x,person.y-context.y)<(person.uniform?2.3:person.posture?1.45:1.25)}
 function staff(person){if(!canTalk(person))return false;begin(person);const ticket=person.id==='lobby:npc:0',popcorn=person.id==='lobby:npc:1';if(ticket){show({name:'Mia',role:'TICKET BOOTH · NPC',line:'Hi! Which article would you like to read?',options:[...rooms.map(r=>({label:`SCREEN ${r.n} · ${r.name}`,action:()=>{close();walkToScreen(r)}})),{label:'Where is the arcade?',action:()=>{close();walkToGame()}}]})}else if(popcorn){show({name:'Leo',role:'POPCORN SHOP · NPC',line:'Hi! Would you like some popcorn?',options:[{label:'A popcorn, please',action:()=>show({name:'Leo',role:'POPCORN SHOP · NPC',line:'Here you go. This one’s on us.',options:[{label:'Thank you!',action:()=>{let snack=document.querySelector('#snack-receipt');if(!snack){snack=document.createElement('span');snack.id='snack-receipt';snack.textContent='POPCORN · ON THE HOUSE';document.querySelector('#lobby-scene').append(snack)}setTimeout(()=>snack.remove(),4500);close()}}]})},{label:'What do you recommend?',action:()=>show({name:'Leo',role:'POPCORN SHOP · NPC',line:'You can read an article in any screening room. There are film quizzes in the arcade, too.',options:[{label:'Sounds good',action:close}]})}]})}else show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'CINEMA GUEST · NPC':'LIVE VISITOR',line:person.npc?'Hi! Are you here to read or play a game?':'Another visitor is exploring the cinema with you.',options:person.npc?[{label:'Recommend a film',action:()=>show({name:'A fellow film lover',line:'Try Family, on screen first. It introduces the three films in this issue.',options:[{label:'Take me to Screen 01',action:()=>{close();walkToScreen(rooms[0])}},{label:'I prefer a game',action:()=>{close();walkToGame()}}]})},{label:'I am here for the arcade',action:()=>show({name:'A fellow film lover',line:'Try EYES ONLY if you remember faces, or FILM CLUB for movie trivia.',options:[{label:'Let’s play',action:()=>{close();walkToGame()}},{label:'Maybe later',action:close}]})},{label:'See you around',action:close}]:[{label:'See you around',action:close}]})}
 function npcReply(active){return new Promise(resolve=>{const timer=setTimeout(()=>{active.cancelDelay=null;resolve()},650);active.cancelDelay=()=>{clearTimeout(timer);resolve()}})}
 function askSeat(person,{seatId,scene,onYes}){
  const active=begin(person),name=person.npc?'A fellow film lover':person.name,role=person.npc?'SEATED GUEST · NPC':'LIVE VISITOR';
  show({name,role,line:`This is seat ${seatId}. Would you like to ask if you can take this seat?`,options:[{label:'Ask to change seats',action:async()=>{
   show({name,role,line:'“Would you mind changing seats?”',options:[]});
   let answer;try{if(person.npc){await npcReply(active);answer=person.id.split(':').at(-1)!=='1'}else answer=await SeenHub.requestSeat(person,{seatId,scene})}catch{answer=null}
   if(!current(active))return;
   const line=answer===true?'Yes — you can have my seat. I’ll find another spot.':answer===false?'No, I’d like to stay in this seat. Thanks for asking.':'No reply yet. They may be reading or away. Try another seat.';
   show({name,role,line,options:[{label:answer===true?'Take the seat':'Choose another seat',action:()=>{close();if(answer===true)onYes()}}]})
  }},{label:'Never mind',action:close}]})
 }
 function incoming(req,onYes){begin(SeenHub.people(req.scene).find(v=>v.id===req.from)||null);let answered=false;const reply=yes=>{answered=true;SeenHub.replySeat(req,yes);close();if(yes)onYes()};show({name:req.name,role:'SEAT REQUEST · LIVE VISITOR',line:`Would you let ${req.name} take seat ${req.seatId}? If you say Yes, you’ll move to another available seat.`,options:[{label:'No · Keep my seat',action:()=>reply(false)},{label:'Yes · I can move',action:()=>reply(true)}],onClose:()=>{if(!answered)SeenHub.replySeat(req,false)}})}
 function nearby({scene,x,y,project,canvas}){context={scene,x,y,project,canvas};if(anchor&&dialog.open){const current=SeenHub.people(scene).find(v=>v.id===anchor.id)||anchor,q=project(current.x+Math.cos(current.heading||0)*.015,current.y+Math.sin(current.heading||0)*.015,1.49-.12*(current.posture||0)+(current.jump||0));const nextKey=[scene,q.x.toFixed(2),q.y.toFixed(2),innerWidth,innerHeight,seenFontRevision].join('|');if(nextKey===placementKey)return;placementKey=nextKey;const r=canvas.getBoundingClientRect();const headX=r.left+q.x,headY=r.top+q.y,ceiling=Math.max(8,document.querySelector('.site-header').getBoundingClientRect().bottom+8);seenSetStyle(dialog,'maxHeight',`${Math.max(110,headY-ceiling-16)}px`);const w=dialog.offsetWidth,h=dialog.offsetHeight,left=Math.max(10,Math.min(innerWidth-w-10,headX-w/2));seenSetStyle(dialog,'left',`${left}px`);seenSetStyle(dialog,'top',`${Math.max(ceiling,headY-h-16)}px`);const tail=`${Math.max(15,Math.min(w-30,headX-left-8))}px`;if(dialog.style.getPropertyValue('--talk-tail-left')!==tail)dialog.style.setProperty('--talk-tail-left',tail)}}

 document.addEventListener('keydown',e=>{if(!dialog.open||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD','Space','Enter'].includes(e.code))return;const nativeButton=(e.code==='Space'||e.code==='Enter')&&e.target.closest?.('button')&&dialog.contains(e.target);if(!nativeButton)e.preventDefault();e.stopImmediatePropagation()},true);
 document.addEventListener('seen-language-change',requestPlacement);addEventListener('resize',requestPlacement);
 return{canTalk,staff,askSeat,incoming,close,nearby};
})();
